INSERT INTO t_p93118852_lineaschool_initiati.fm_pnl_fact_manual (month_id, line, label, amount, sort, note) VALUES
 ('2025-11','teachers','Педагоги',76000.00,30,'По проведённым в ноябре урокам. Шишаева 78 инд: 1–15 ноя 13 300 (выпл. 25.11) + 16–30 ноя 14 000 (выпл. 14.12) = 27 300; Мельникова 47 групп: 1–15 ноя 8 700 + 16–30 ноя 18 650 = 27 350; Камнева 33 инд: 5 950 (25.11) + 5 600 (14.12) = 11 550; Еремина 28 инд × 350 = 9 800 (10 за 1–15 + 18 за 16–30). Уроки руководителя не учитываются')
